(() => {
'use strict';
const canvas = document.getElementById('game');
const ctx = canvas.getContext('2d');
const W = 800, H = 600, HUD_H = 48;
const dpr = Math.min(window.devicePixelRatio || 1, 2);
canvas.width = W * dpr;
canvas.height = H * dpr;
ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

// ---- audio ----
let audioCtx = null;
function beep(freq, dur = 0.06, type = 'square', vol = 0.04) {
  try {
    if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
    const o = audioCtx.createOscillator();
    const g = audioCtx.createGain();
    o.type = type; o.frequency.value = freq;
    g.gain.setValueAtTime(vol, audioCtx.currentTime);
    g.gain.exponentialRampToValueAtTime(0.0001, audioCtx.currentTime + dur);
    o.connect(g).connect(audioCtx.destination);
    o.start(); o.stop(audioCtx.currentTime + dur);
  } catch (e) {}
}

// ---- state ----
const ROWS = 6, COLS = 12;
const COLORS = ['#ef4444','#f97316','#facc15','#22c55e','#3b82f6','#a855f7'];
let state, score, high, lives, level, blocks, balls, powerups, paddle, keys, timers, msg, msgTimer, shake;
high = Number(localStorage.getItem('breakout-high') || 0);

function ballSpeed() { return Math.min(300 + (level - 1) * 18, 470); }

function resetGame() {
  score = 0; lives = 3; level = 1;
  paddle = { x: W/2 - 55, w: 110, h: 14, y: H - 36 };
  buildLevel();
  state = 'ready';
}

function buildLevel() {
  blocks = []; powerups = [];
  balls = [];
  timers = { expand: 0, slow: 0 };
  const top = HUD_H + 30;
  const gap = 6;
  const bw = (W - 40 - gap * (COLS - 1)) / COLS;
  const bh = 22;
  const pattern = (level - 1) % 3;
  for (let r = 0; r < ROWS; r++) {
    for (let c = 0; c < COLS; c++) {
      if (pattern === 1 && (r + c) % 2 === 1) continue;
      if (pattern === 2 && (c < Math.floor(r / 2) || c >= COLS - Math.floor(r / 2))) continue;
      const hp = (level >= 3 && r === 0) ? 2 : 1;
      blocks.push({ x: 20 + c * (bw + gap), y: top + r * (bh + gap), w: bw, h: bh, color: COLORS[r], points: (ROWS - r) * 10, hp });
    }
  }
  spawnBallOnPaddle();
}

function spawnBallOnPaddle() {
  balls = [{ x: paddle.x + paddle.w / 2, y: paddle.y - 10, vx: 0, vy: 0, r: 7, stuck: true }];
}
```

