function update(dt) {
  // paddle keyboard
  const pv = 560;
  if (keys.ArrowLeft || keys.a) paddle.x -= pv*dt;
  if (keys.ArrowRight || keys.d) paddle.x += pv*dt;
  paddle.x = Math.max(10, Math.min(W - 10 - paddle.w, paddle.x));

  if (state !== 'playing') {
    if (state === 'ready') for (const b of balls) { b.x = paddle.x + paddle.w/2; b.y = paddle.y - b.r - 2; }
    if (state === 'levelclear') { msgTimer -= dt; if (msgTimer <= 0) { level++; buildLevel(); state='ready'; } }
    return;
  }

  timers.expand = Math.max(0, timers.expand - dt);
  timers.slow = Math.max(0, timers.slow - dt);
  paddle.w = timers.expand > 0 ? 165 : 110;
  paddle.x = Math.max(10, Math.min(W - 10 - paddle.w, paddle.x));

  const slowMul = timers.slow > 0 ? 0.65 : 1;

  for (let i = balls.length - 1; i >= 0; i--) {
    const b = balls[i];
    const steps = Math.max(1, Math.ceil(ballSpeed()*slowMul*dt / 5));
    const sdt = dt / steps;
    let lost = false;
    for (let s = 0; s < steps && !lost; s++) {
      b.x += b.vx * slowMul * sdt;
      b.y += b.vy * slowMul * sdt;
      // walls
      if (b.x - b.r < 10) { b.x = 10 + b.r; b.vx = Math.abs(b.vx); beep(220,.03,'triangle'); }
      if (b.x + b.r > W-10) { b.x = W-10-b.r; b.vx = -Math.abs(b.vx); beep(220,.03,'triangle'); }
      if (b.y - b.r < HUD_H) { b.y = HUD_H + b.r; b.vy = Math.abs(b.vy); beep(220,.03,'triangle'); }
      if (b.y - b.r > H) { lost = true; break; }
      // paddle
      if (b.vy > 0 && b.y + b.r >= paddle.y && b.y - b.r <= paddle.y + paddle.h && b.x >= paddle.x - b.r && b.x <= paddle.x + paddle.w + b.r) {
        const rel = (b.x - (paddle.x + paddle.w/2)) / (paddle.w/2);
        const ang = rel * (Math.PI/3);
        const sp = Math.hypot(b.vx, b.vy) || ballSpeed();
        b.vx = Math.sin(ang) * sp;
        b.vy = -Math.abs(Math.cos(ang) * sp);
        if (Math.abs(b.vy) < sp*0.25) b.vy = -sp*0.25;
        b.y = paddle.y - b.r - 0.5;
        beep(330,.04,'square');
      }
      // blocks
      for (const bl of blocks) {
        if (bl.hp <= 0) continue;
        if (b.x + b.r > bl.x && b.x - b.r < bl.x + bl.w && b.y + b.r > bl.y && b.y - b.r < bl.y + bl.h) {
          const ox = Math.min(b.x + b.r - bl.x, bl.x + bl.w - (b.x - b.r));
          const oy = Math.min(b.y + b.r - bl.y, bl.y + bl.h - (b.y - b.r));
          if (ox < oy) { b.vx = (b.x < bl.x + bl.w/2) ? -Math.abs(b.vx) : Math.abs(b.vx); b.x += (b.vx<0? -ox: ox); }
```

