function maybeDropPowerup(bl) {
  if (Math.random() > 0.14) return;
  const types = ['E','M','S','+'];
  const weights = [0.35,0.3,0.2,0.15];
  let x = Math.random(), acc = 0, type = 'E';
  for (let i=0;i<types.length;i++){ acc += weights[i]; if (x <= acc){ type = types[i]; break; } }
  powerups.push({ x: bl.x + bl.w/2, y: bl.y + bl.h/2, type });
}
```

