function applyPowerup(t) {
  beep(760,.08,'sine',.06);
  if (t === 'E') timers.expand = 10;
  if (t === 'S') timers.slow = 8;
  if (t === '+') lives = Math.min(lives + 1, 6);
  if (t === 'M') {
    const src = balls[0];
    if (src) {
      const sp = Math.hypot(src.vx, src.vy) || ballSpeed();
      for (const off of [-0.5, 0.5]) {
        const a = Math.atan2(src.vy, src.vx) + off;
        balls.push({ x: src.x, y: src.y, vx: Math.cos(a)*sp, vy: Math.sin(a)*sp, r: 7, stuck: false });
      }
    }
  }
}
