    color: #93c5fd;
  }
  #wrap {
    width: min(96vw, 800px);
  }
  canvas {
    display: block;
    width: 100%;
    aspect-ratio: 4 / 3;
    border-radius: 12px;
    box-shadow: 0 12px 40px rgba(59,130,246,.18), 0 0 0 1px rgba(148,163,184,.15);
    background: #0b1020;
    touch-action: none;
    cursor: none;
  }
  footer {
    font-size: 13px;
    color: #94a3b8;
    text-align: center;
    line-height: 1.7;
  }
  kbd {
    background: #1e293b;
    border: 1px solid #334155;
    border-bottom-width: 2px;
    border-radius: 5px;
    padding: 1px 6px;
    font-family: inherit;
    font-size: 12px;
  }
</style>
</head>
<body>
<h1>ブロック崩し</h1>
<div id="wrap">
  <canvas id="game"></canvas>
</div>
<footer>
  <kbd>マウス</kbd> / <kbd>←</kbd><kbd>→</kbd> でパドル移動　
  <kbd>スペース</kbd> または <kbd>クリック</kbd> で発射　
  <kbd>P</kbd> 一時停止　<kbd>R> リスタート
</footer>
<script>
(() => {
'use strict';

const canvas = document.getElementById('game');
const ctx = canvas.getContext('2d');
const W = 800, H = 600, HUD_H = 48;
const dpr = Math.min(window.devicePixelRatio || 1, 2);
canvas.width = W * dpr;
canvas.height = H * dpr;
ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

/* ---------- 効果音 ---------- */
let audioCtx = null;
function beep(freq, dur = 0.06, type = 'square', vol = 0.04) {
  try {
    if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
    if (audioCtx.state === 'suspended') audioCtx.resume();
    const o = audioCtx.createOscillator();
    const g = audioCtx.createGain();
    o.type = type;
    o.frequency.value = freq;
    g.gain.setValueAtTime(vol, audioCtx.currentTime);
    g.gain.exponentialRampToValueAtTime(0.0001, audioCtx.currentTime + dur);
    o.connect(g).connect(audioCtx.destination);
    o.start();
    o.stop(audioCtx.currentTime + dur);
  } catch (e) { /* 音が出なくても無視 */ }
}

/* ---------- 定数 ---------- */
const ROWS = 6, COLS = 12;
const COLORS = ['#ef4444', '#f97316', '#facc15', '#22c55e', '#3b82f6', '#a855f7'];
const PADDLE_BASE_W = 110, PADDLE_EXPAND_W = 165;

/* ---------- 状態 ---------- */
let state, score, lives, level, blocks, balls, powerups, paddle, timers, msgTimer;
let high = 0;
try { high = Number(localStorage.getItem('breakout-high') || 0); } catch (e) {}

const keys = {};

function ballSpeed() { return Math.min(300 + (level - 1) * 18, 470); }

function saveHigh() {
  try { localStorage.setItem('breakout-high', String(high)); } catch (e) {}
}

function resetGame() {
  score = 0;
  lives = 3;
  level = 1;
  paddle = { x: W / 2 - PADDLE_BASE_W / 2, y: H - 36, w: PADDLE_BASE_W, h: 14 };
  buildLevel();
  state = 'ready';
}

function buildLevel() {
  blocks = [];
  powerups = [];
  timers = { expand: 0, slow: 0 };
  const top = HUD_H + 30;
  const gap = 6;
  const bw = (W - 40 - gap * (COLS - 1)) / COLS;
  const bh = 22;
  const pattern = (level - 1) % 3;
  for (let r = 0; r < ROWS; r++) {
    for (let c = 0; c < COLS; c++) {
      if (pattern === 1 && (r + c) % 2 === 1) continue;               // チェッカー柄
      if (pattern === 2 && (c < (r >> 1) || c >= COLS - (r >> 1))) continue; // 逆ピラミッド
      const hp = (level >= 3 && r === 0) ? 2 : 1;                     // 上段は硬くなる
      blocks.push({
        x: 20 + c * (bw + gap),
        y: top + r * (bh + gap),
        w: bw, h: bh,
        color: COLORS[r],
        points: (ROWS - r) * 10,
        hp
      });
    }
  }
  spawnBallOnPaddle();
}

function spawnBallOnPaddle() {
  balls = [{ x: paddle.x + paddle.w / 2, y: paddle.y - 9, vx: 0, vy: 0, r: 7, stuck: true }];
}

function launch() {
  let launched = false;
  for (const b of balls) {
    if (b.stuck) {
      b.stuck = false;
      const a = -Math.PI / 2 + (Math.random() * 0.6 - 0.3);
      const s = ballSpeed();
      b.vx = Math.cos(a) * s;
      b.vy = Math.sin(a) * s;
      launched = true;
    }
  }
  if (state === 'ready') state = 'playing';
  if (launched) beep(440, 0.05);
}

/* ---------- パワーアップ ---------- */
function maybeDropPowerup(bl) {
  if (Math.random() > 0.14) return;
  const types = ['E', 'M', 'S', '+'];
  const weights = [0.35, 0.3, 0.2, 0.15];
  const x = Math.random();
  let acc = 0, type = 'E';
  for (let i = 0; i < types.length; i++) {
    acc += weights[i];
    if (x <= acc) { type = types[i]; break; }
  }
  powerups.push({ x: bl.x + bl.w / 2, y: bl.y + bl.h / 2, type });
}

function applyPowerup(t) {
  beep(760, 0.08, 'sine', 0.06);
  if (t === 'E') timers.expand = 10;
  if (t === 'S') timers.slow = 8;
  if (t === '+') lives = Math.min(lives + 1, 6);
  if (t === 'M') {
    const src = balls[0];
    if (src) {
      const sp = Math.hypot(src.vx, src.vy) || ballSpeed();
      const base = Math.atan2(src.vy, src.vx) || -Math.PI / 2;
      for (const off of [-0.5, 0.5]) {
        const a = base + off;
        balls.push({ x: src.x, y: src.y, vx: Math.cos(a) * sp, vy: Math.sin(a) * sp, r: 7, stuck: false });
      }
    }
  }
}

/* ---------- 更新 ---------- */
function enforceMinVy(b) {
  const sp = Math.hypot(b.vx, b.vy);
  if (sp === 0) return;
  const minVy = sp * 0.18;
  if (Math.abs(b.vy) < minVy) {
    b.vy = (b.vy >= 0 ? 1 : -1) * minVy;
    const maxVx = Math.sqrt(sp * sp - minVy * minVy);
    b.vx = (b.vx >= 0 ? 1 : -1) * maxVx;
  }
}

function update(dt) {
  // パドル移動（どの状態でも可）
  const pv = 560;
  if (keys['ArrowLeft'] || keys['a']) paddle.x -= pv * dt;
  if (keys['ArrowRight'] || keys['d']) paddle.x += pv * dt;
  paddle.x = Math.max(10, Math.min(W - 10 - paddle.w, paddle.x));

  if (state === 'ready') {
    for (const b of balls) { b.x = paddle.x + paddle.w / 2; b.y = paddle.y - b.r - 2; }
    return;
  }
  if (state === 'levelclear') {
    msgTimer -= dt;
    if (msgTimer <= 0) { level++; buildLevel(); state = 'ready'; }
    return;
  }
  if (state !== 'playing') return;

  timers.expand = Math.max(0, timers.expand - dt);
  timers.slow = Math.max(0, timers.slow - dt);
  paddle.w = timers.expand > 0 ? PADDLE_EXPAND_W : PADDLE_BASE_W;
  paddle.x = Math.max(10, Math.min(W - 10 - paddle.w, paddle.x));

  const slowMul = timers.slow > 0 ? 0.65 : 1;

  for (let i = balls.length - 1; i >= 0; i--) {
    const b = balls[i];
    const steps = Math.max(1, Math.ceil(ballSpeed() * slowMul * dt / 5));
    const sdt = dt / steps;
    let lost = false;

    for (let s = 0; s < steps && !lost; s++) {
      b.x += b.vx * slowMul * sdt;
      b.y += b.vy * slowMul * sdt;

      // 壁
      if (b.x - b.r < 10)     { b.x = 10 + b.r;     b.vx = Math.abs(b.vx);  beep(220, 0.03, 'triangle'); }
      if (b.x + b.r > W - 10) { b.x = W - 10 - b.r; b.vx = -Math.abs(b.vx); beep(220, 0.03, 'triangle'); }
      if (b.y - b.r < HUD_H)  { b.y = HUD_H + b.r;  b.vy = Math.abs(b.vy);  beep(220, 0.03, 'triangle'); }
      if (b.y - b.r > H) { lost = true; break; }

      // パドル
      if (b.vy > 0 &&
          b.y + b.r >= paddle.y && b.y - b.r <= paddle.y + paddle.h &&
          b.x >= paddle.x - b.r && b.x <= paddle.x + paddle.w + b.r) {
        const rel = (b.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
        const ang = Math.max(-1, Math.min(1, rel)) * (Math.PI / 3);
        const sp = Math.hypot(b.vx, b.vy) || ballSpeed();
        b.vx = Math.sin(ang) * sp;
        b.vy = -Math.abs(Math.cos(ang) * sp);
        if (Math.abs(b.vy) < sp * 0.25) b.vy = -sp * 0.25;
        b.y = paddle.y - b.r - 0.5;
        beep(330, 0.04);
      }

      // ブロック（1サブステップにつき1個）
      for (const bl of blocks) {
        if (bl.hp <= 0) continue;
        if (b.x + b.r > bl.x && b.x - b.r < bl.x + bl.w &&
            b.y + b.r > bl.y && b.y - b.r < bl.y + bl.h) {
          const ox = Math.min(b.x + b.r - bl.x, bl.x + bl.w - (b.x - b.r));
          const oy = Math.min(b.y + b.r - bl.y, bl.y + bl.h - (b.y - b.r));
          const cx = bl.x + bl.w / 2, cy = bl.y + bl.h / 2;
          if (ox < oy) {
            if (b.x < cx) { b.x -= ox; b.vx = -Math.abs(b.vx); }
            else          { b.x += ox; b.vx =  Math.abs(b.vx); }
          } else {
            if (b.y < cy) { b.y -= oy; b.vy = -Math.abs(b.vy); }
            else          { b.y += oy; b.vy =  Math.abs(b.vy); }
          }
          enforceMinVy(b);
          bl.hp--;
          if (bl.hp <= 0) {
            score += bl.points;
            if (score > high) { high = score; saveHigh(); }
            maybeDropPowerup(bl);
            beep(600 + bl.points, 0.05, 'square', 0.05);
          } else {
            beep(520, 0.04, 'triangle');
          }
          break;
        }
      }
    }

    if (lost) balls.splice(i, 1);
  }

  // ボール消失
  if (balls.length === 0) {
    lives--;
    beep(120, 0.3, 'sawtooth', 0.06);
    if (lives <= 0) {
      state = 'gameover';
    } else {
      spawnBallOnPaddle();
      state = 'ready';
    }
  }

  // パワーアップ落下
  for (let i = powerups.length - 1; i >= 0; i--) {
    const p = powerups[i];
    p.y += 140 * dt;
    if (p.y > H + 20) { powerups.splice(i, 1); continue; }
    if (p.y + 10 >= paddle.y && p.y - 10 <= paddle.y + paddle.h &&
        p.x >= paddle.x - 10 && p.x <= paddle.x + paddle.w + 10) {
      applyPowerup(p.type);
      powerups.splice(i, 1);
    }
  }

  // 面クリア
  if (blocks.every(bl => bl.hp <= 0)) {
    state = 'levelclear';
    msgTimer = 1.6;
    beep(880, 0.1, 'square', 0.05);
    setTimeout(() => beep(1175, 0.18, 'square', 0.05), 130);
  }
}

/* ---------- 描画 ---------- */
function rr(x, y, w, h, r) {
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.arcTo(x + w, y, x + w, y + h, r);
  ctx.arcTo(x + w, y + h, x, y + h, r);
  ctx.arcTo(x, y + h, x, y, r);
  ctx.arcTo(x, y, x + w, y, r);
  ctx.closePath();
}

function draw() {
  // 背景
  const g = ctx.createLinearGradient(0, 0, 0, H);
  g.addColorStop(0, '#0b1020');
  g.addColorStop(1, '#151b30');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, H);

  // 遊び場枠
  ctx.strokeStyle = 'rgba(148,163,184,.25)';
  ctx.lineWidth = 1;
  ctx.strokeRect(10.5, HUD_H + 0.5, W - 21, H - HUD_H - 1);

  // ブロック
  for (const bl of blocks) {
    if (bl.hp <= 0) continue;
    ctx.fillStyle = bl.color;
    rr(bl.x, bl.y, bl.w, bl.h, 4);
    ctx.fill();
    // 光沢
    ctx.fillStyle = 'rgba(255,255,255,.22)';
    rr(bl.x + 2, bl.y + 2, bl.w - 4, bl.h * 0.35, 3);
    ctx.fill();
    if (bl.hp >= 2) {
      ctx.strokeStyle = 'rgba(255,255,255,.55)';
      rr(bl.x + 1.5, bl.y + 1.5, bl.w - 3, bl.h - 3, 3);
      ctx.stroke();
    } else if (bl.points !== undefined && blocks.indexOf(bl) >= 0 && level >= 3 && bl.y < HUD_H + 30 + 28) {
      // 2回壊した跡（ひび）
      ctx.strokeStyle = 'rgba(0,0,0,.45)';
      ctx.beginPath();
      ctx.moveTo(bl.x + bl.w * 0.3, bl.y + 3);
      ctx.lineTo(bl.x + bl.w * 0.45, bl.y + bl.h * 0.5);
      ctx.lineTo(bl.x + bl.w * 0.35, bl.y + bl.h - 3);
      ctx.moveTo(bl.x + bl.w * 0.6, bl.y + 4);
      ctx.lineTo(bl.x + bl.w * 0.55, bl.y + bl.h * 0.6);
      ctx.stroke();
    }
  }

  // パワーアップ
  const puColor = { E: '#22c55e', M: '#3b82f6', S: '#a855f7', '+': '#ef4444' };
  for (const p of powerups) {
    ctx.fillStyle = puColor[p.type];
    rr(p.x - 11, p.y - 11, 22, 22, 6);
    ctx.fill();
    ctx.strokeStyle = 'rgba(255,255,255,.6)';
    rr(p.x - 11, p.y - 11, 22, 22, 6);
    ctx.stroke();
    ctx.fillStyle = '#fff';
    ctx.font = '700 13px system-ui, sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(p.type, p.x, p.y + 1);
  }

  // パドル
  const pg = ctx.createLinearGradient(0, paddle.y, 0, paddle.y + paddle.h);
  pg.addColorStop(0, '#e0f2fe');
  pg.addColorStop(1, '#38bdf8');
  ctx.fillStyle = pg;
  rr(paddle.x, paddle.y, paddle.w, paddle.h, 7);
  ctx.fill();
  ctx.shadowColor = 'rgba(56,189,248,.7)';
  ctx.shadowBlur = 12;
  rr(paddle.x, paddle.y, paddle.w, paddle.h, 7);
  ctx.fill();
  ctx.shadowBlur = 0;

  // ボール
  for (const b of balls) {
    ctx.shadowColor = 'rgba(255,255,255,.8)';
    ctx.shadowBlur = 10;
    ctx.fillStyle = '#f8fafc';
    ctx.beginPath();
    ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2);
    ctx.fill();
    ctx.shadowBlur = 0;
  }

  // HUD
  ctx.fillStyle = '#e2e8f0';
  ctx.font = '600 15px system-ui, sans-serif';
  ctx.textBaseline = 'middle';
  ctx.textAlign = 'left';
  ctx.fillText('スコア ' + score, 16, 16);
  ctx.fillStyle = '#94a3b8';
  ctx.fillText('残機 ' + '●'.repeat(Math.max(0, lives)), 16, 35);
  ctx.fillStyle = '#93c5fd';
  ctx.textAlign = 'center';
  ctx.font = '700 16px system-ui, sans-serif';
  ctx.fillText('LEVEL ' + level, W / 2, 25);
  ctx.fillStyle = '#94a3b8';
  ctx.font = '600 15px system-ui, sans-serif';
  ctx.textAlign = 'right';
  ctx.fillText('ハイスコア ' + high, W - 16, 16);
  let rightLine = 35;
  if (timers.expand > 0) { ctx.fillText('パドル拡大 ' + Math.ceil(timers.expand) + 's', W - 16, rightLine); rightLine += 0; }
  if (timers.slow > 0)   { ctx.fillStyle = '#c4b5fd'; ctx.fillText('スロー ' + Math.ceil(timers.slow) + 's', W - 140, 35); }

  // オーバーレイ
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  if (state === 'ready') {
    ctx.fillStyle = 'rgba(248,250,252,.85)';
    ctx.font = '600 18px system-ui, sans-serif';
    ctx.fillText('スペース / クリック で発射', W / 2, H * 0.62);
  } else if (state === 'paused') {
    overlay();
    ctx.fillStyle = '#f8fafc';
    ctx.font = '700 34px system-ui, sans-serif';
    ctx.fillText('一時停止', W / 2, H / 2 - 14);
    ctx.font = '500 15px system-ui, sans-serif';
    ctx.fillStyle = '#94a3b8';
    ctx.fillText('P で再開', W / 2, H / 2 + 24);
  } else if (state === 'levelclear') {
    overlay();
    ctx.fillStyle = '#a7f3d0';
    ctx.font = '700 34px system-ui, sans-serif';
    ctx.fillText('LEVEL ' + level + ' クリア！', W / 2, H / 2 - 14);
    ctx.font = '500 15px system-ui, sans-serif';
    ctx.fillStyle = '#94a3b8';
    ctx.fillText('次のレベルへ…', W / 2, H / 2 + 24);
  } else if (state === 'gameover') {
    overlay();
    ctx.fillStyle = '#fca5a5';
    ctx.font = '700 38px system-ui, sans-serif';
    ctx.fillText('ゲームオーバー', W / 2, H / 2 - 34);
    ctx.fillStyle = '#e2e8f0';
    ctx.font = '600 18px system-ui, sans-serif';
    ctx.fillText('スコア ' + score + '　ハイスコア ' + high, W / 2, H / 2 + 8);
    ctx.font = '500 15px system-ui, sans-serif';
    ctx.fillStyle = '#94a3b8';
    ctx.fillText('R またはクリック でリスタート', W / 2, H / 2 + 40);
  }
}

function overlay() {
  ctx.fillStyle = 'rgba(2,6,23,.6)';
  ctx.fillRect(10, HUD_H, W - 20, H - HUD_H - 10);
}

/* ---------- 入力 ---------- */
window.addEventListener('keydown', e => {
  if (['ArrowLeft', 'ArrowRight', ' '].includes(e.key)) e.preventDefault();
  keys[e.key] = true;
  if (e.key === ' ') {
    if (state === 'ready') launch();
    else if (state === 'paused') state = 'playing';
    else if (state === 'gameover') resetGame();
  }
  if (e.key === 'p' || e.key === 'P' || e.key === 'Escape') {
    if (state === 'playing') state = 'paused';
    else if (state === 'paused') state = 'playing';
  }
  if (e.key === 'r' || e.key === 'R') resetGame();
});
window.addEventListener('keyup', e => { keys[e.key] = false; });

function movePaddleTo(clientX) {
  const rect = canvas.getBoundingClientRect();
  const x = (clientX - rect.left) * (W / rect.width);
  paddle.x = Math.max(10, Math.min(W - 10 - paddle.w, x - paddle.w / 2));
}
canvas.addEventListener('mousemove', e => movePaddleTo(e.clientX));
canvas.addEventListener('mousedown', () => {
  if (state === 'ready') launch();
  else if (state === 'gameover') resetGame();
});
canvas.addEventListener('touchmove', e => {
  e.preventDefault();
  movePaddleTo(e.touches[0].clientX);
}, { passive: false });
canvas.addEventListener('touchstart', e => {
  e.preventDefault();
  movePaddleTo(e.touches[0].clientX);
  if (state === 'ready') launch();
  else if (state === 'gameover') resetGame();
}, { passive: false });

/* ---------- メインループ ---------- */
let last = performance.now();
function frame(now) {
  const dt = Math.min((now - last) / 1000, 1 / 30);
  last = now;
  update(dt);
  draw();
  requestAnimationFrame(frame);
}

resetGame();
requestAnimationFrame(frame);
})();
</script>
</body>
</html>
